import { useEffect, useMemo, useState, type FormEvent } from "react";
import { Link, useNavigate, useParams, useSearchParams } from "react-router-dom";
import { useAdminQuery, useAdminMutation } from "../../app/query-client/hooks";
import { AdminRequestError } from "../../app/query-client/apiState";
import { useAdminContext, useEffectivePermissions } from "../../app/site-context/AdminContext";
import { useDirtyState } from "../../app/site-context/DirtyStateContext";
import { PageFrame } from "../PageFrame";
import { QueryState } from "../QueryStates";
import { arrayValue, asRecord, asRecords, booleanValue, formatDate, listItems, numberValue, stringValue, type UnknownRecord } from "../recordUtils";
import { Alert, Button, Checkbox, ConfirmDialog, DataTable, EmptyState, FilterBar, FormSection, JsonSummary, Modal, PageHeader, Pagination, SelectField, StatCard, StatusBadge, SuccessState, TextArea, TextField } from "../../ui/components";
import { CalendarOperationsPanel, MediaReplacePanel, PostsBulkPanel, TagMergePanel } from "./SiteAdvancedControls";
import { MediaPicker } from "./EditorAssist";

function sitePath(siteKey:string, path:string){return `/site/${encodeURIComponent(siteKey)}${path}`}
function useSiteKey(){const p=useParams(); return p.siteKey??""}
function mutationError(error:unknown): string {if(error instanceof AdminRequestError){if(error.failure.uiState==="CONFLICT")return "The server rejected a stale or conflicting write. Reload current state before retrying.";if(error.failure.uiState==="VALIDATION"){const detail=error.failure.fieldErrors?.find(item=>item.message);return detail?.message??"Server validation rejected one or more fields."}if(error.failure.uiState==="DENIED")return "The server denied this action under current authority.";}return "The change could not be completed."}

export function SiteDashboardPage(){const site=useAdminContext().site!;const permissions=useEffectivePermissions();const query=useAdminQuery<UnknownRecord>("API15-S-002",{path:{site_key:site.site_key}});const recentQuery=useAdminQuery<UnknownRecord>("API15-S-010",{path:{site_key:site.site_key},query:{page:1,page_size:5,sort:"UPDATED_DESC"}},permissions.includes("posts.view"));const calendarQuery=useAdminQuery<UnknownRecord>("API15-S-095",{path:{site_key:site.site_key}},permissions.includes("calendar.view"));const metrics=asRecords(asRecord(query.data).metrics);const recent=listItems(recentQuery.data);const upcoming=asRecords(asRecord(calendarQuery.data).items).filter(item=>stringValue(item,"status")==="SCHEDULED").slice(0,5);return <PageFrame pageId="ADM-S-DASH-01" actions={permissions.includes("posts.create")?<Link className="bp-button bp-button--primary" to={sitePath(site.site_key,"/posts/new")}>Create Blog</Link>:undefined}><QueryState isLoading={query.isLoading} error={query.error} hasData={Boolean(query.data)} retry={()=>void query.refetch()}><div className="bp-grid bp-grid--stats">{metrics.map((m,i)=><StatCard key={`${stringValue(m,"key")}-${i}`} label={stringValue(m,"label")} value={stringValue(m,"value","0")}/>)}</div>{recentQuery.error||calendarQuery.error?<Alert tone="warning">Dashboard totals are available, but one optional list could not be loaded. You can continue working and retry from its full page.</Alert>:null}<div className="bp-grid bp-grid--2"><section className="bp-card"><div className="bp-card-header"><div><h2>Recent blogs</h2><p>Latest updates for this website.</p></div><Link className="bp-button bp-button--tertiary" to={sitePath(site.site_key,"/posts")}>View all</Link></div>{recent.length?<DataTable rows={recent} rowKey={r=>stringValue(r,"post_id")} columns={[{key:"title",header:"Title",cell:r=><Link className="bp-table-primary" to={sitePath(site.site_key,`/posts/${stringValue(r,"post_id")}`)}>{stringValue(r,"title","Untitled")}</Link>},{key:"status",header:"Status",cell:r=><StatusBadge value={stringValue(r,"status","DRAFT")}/>},{key:"updated",header:"Updated",cell:r=>formatDate(r.updated_at)}]}/>:<EmptyState title="No blogs yet" description="Create the first blog for this website."/>}</section><section className="bp-card"><div className="bp-card-header"><div><h2>Upcoming</h2><p>Scheduled publication times use the website timezone.</p></div><Link className="bp-button bp-button--tertiary" to={sitePath(site.site_key,"/calendar")}>Open calendar</Link></div>{upcoming.length?<DataTable rows={upcoming} rowKey={r=>stringValue(r,"post_id")} columns={[{key:"title",header:"Title",cell:r=>stringValue(r,"title","Untitled")},{key:"scheduled",header:"Scheduled",cell:r=>formatDate(r.scheduled_for)}]}/>:<EmptyState title="Nothing scheduled"/>}</section></div></QueryState></PageFrame>}

export function PostsListPage(){const site=useAdminContext().site!;const permissions=useEffectivePermissions();const [params,setParams]=useSearchParams();const page=Number(params.get("page")??1)||1;const status=params.get("status")??"";const search=params.get("search")??"";const [draftSearch,setDraftSearch]=useState(search);const query=useAdminQuery<UnknownRecord>("API15-S-010",{path:{site_key:site.site_key},query:{status:status||undefined,search:search||undefined,page,page_size:20,sort:"UPDATED_DESC"}});const authorsQuery=useAdminQuery<UnknownRecord>("API15-S-050",{path:{site_key:site.site_key},query:{page:1,page_size:100}},permissions.includes("authors.view"));const categoriesQuery=useAdminQuery<UnknownRecord>("API15-S-030",{path:{site_key:site.site_key},query:{page:1,page_size:100}},permissions.includes("categories.view"));const items=listItems(query.data);const authors=new Map(listItems(authorsQuery.data).map(item=>[stringValue(item,"author_id"),stringValue(item,"display_name")]));const categories=new Map(listItems(categoriesQuery.data).map(item=>[stringValue(item,"category_id"),stringValue(item,"name")]));const pageMeta=asRecord(asRecord(query.data).page);const totalPages=numberValue(pageMeta,"total_pages",items.length<20?page:page+1);function apply(){const next=new URLSearchParams(params);draftSearch?next.set("search",draftSearch):next.delete("search");next.set("page","1");setParams(next)}function setStatus(value:string){const next=new URLSearchParams(params);value?next.set("status",value):next.delete("status");next.set("page","1");setParams(next)}return <PageFrame pageId="ADM-S-POST-01" actions={permissions.includes("posts.create")?<Link className="bp-button bp-button--primary" to={sitePath(site.site_key,"/posts/new")}>Create Blog</Link>:undefined}><FilterBar><TextField label="Search blogs" value={draftSearch} onChange={e=>setDraftSearch(e.target.value)} onKeyDown={e=>{if(e.key==="Enter"){e.preventDefault();apply()}}}/><SelectField label="Status" value={status} onChange={e=>setStatus(e.target.value)}><option value="">All statuses</option>{["DRAFT","SCHEDULED","PUBLISHED","ARCHIVED","TRASH"].map(s=><option key={s}>{s}</option>)}</SelectField><Button onClick={apply}>Apply</Button></FilterBar><QueryState isLoading={query.isLoading} error={query.error} hasData={Boolean(query.data)} retry={()=>void query.refetch()} empty={<EmptyState title="No blogs found" description="Create a blog or change the current filters."/>}><DataTable caption="Blogs" rows={items} rowKey={r=>stringValue(r,"post_id")} columns={[{key:"title",header:"Title",cell:r=><Link className="bp-table-primary" to={sitePath(site.site_key,`/posts/${stringValue(r,"post_id")}`)}>{stringValue(r,"title","Untitled draft")}</Link>},{key:"author",header:"Author",cell:r=>authors.get(stringValue(r,"author_site_profile_id"))??"—"},{key:"category",header:"Category",cell:r=>arrayValue(r,"category_ids").map(id=>categories.get(String(id))??String(id)).join(", ")||"—"},{key:"status",header:"Status",cell:r=><StatusBadge value={stringValue(r,"status","DRAFT")}/>},{key:"updated",header:"Updated",cell:r=>formatDate(r.updated_at)},{key:"actions",header:"Actions",cell:r=><div className="bp-row-actions"><Link className="bp-button bp-button--tertiary" to={sitePath(site.site_key,`/posts/${stringValue(r,"post_id")}`)}>Edit</Link></div>}]} /><Pagination page={page} onPrevious={()=>{const n=new URLSearchParams(params);n.set("page",String(Math.max(1,page-1)));setParams(n)}} onNext={()=>{const n=new URLSearchParams(params);n.set("page",String(page+1));setParams(n)}} hasNext={page<totalPages}/><PostsBulkPanel siteKey={site.site_key} items={items} onComplete={()=>void query.refetch()}/></QueryState></PageFrame>}

export function RevisionHistoryPage(){const site=useAdminContext().site!;const {postId=""}=useParams();const permissions=useEffectivePermissions();const query=useAdminQuery<UnknownRecord>("API15-S-026",{path:{site_key:site.site_key,post_id:postId},query:{page:1,page_size:50}});const postQuery=useAdminQuery<UnknownRecord>("API15-S-012",{path:{site_key:site.site_key,post_id:postId}});const post=asRecord(asRecord(postQuery.data).post);const restore=useAdminMutation<UnknownRecord>("API15-S-027",{invalidate:["API15-S-012"]});const [target,setTarget]=useState<string>();const items=listItems(query.data);const expectedVersion=Number(post.version??0);const canRestore=permissions.includes("posts.edit")&&permissions.includes("posts.revisions.restore");return <PageFrame pageId="ADM-S-POST-04" context={`Post ${postId} · current version ${expectedVersion||"loading"}`} back={<Link to={sitePath(site.site_key,`/posts/${postId}`)}>← Back to editor</Link>}><QueryState isLoading={query.isLoading||postQuery.isLoading} error={query.error??postQuery.error} hasData={Boolean(query.data&&postQuery.data)} retry={()=>{void query.refetch();void postQuery.refetch()}}><DataTable caption="Formal revisions" rows={items} rowKey={r=>stringValue(r,"revision_id")} columns={[{key:"version",header:"Version",cell:r=><span className="bp-table-primary">v{stringValue(r,"version")}</span>},{key:"at",header:"Created",cell:r=>formatDate(r.created_at)},{key:"actor",header:"Created by",cell:r=>stringValue(r,"created_by_admin_id")},{key:"action",header:"Action",cell:r=>canRestore?<Button variant="tertiary" onClick={()=>setTarget(stringValue(r,"revision_id"))}>Restore</Button>:"—"}]} />{restore.isError?<Alert tone="danger">{mutationError(restore.error)}</Alert>:null}{restore.isSuccess?<SuccessState>Revision restore accepted. The post now has a new authoritative version; reopen the editor before editing further.</SuccessState>:null}</QueryState><ConfirmDialog open={Boolean(target)} title="Restore this revision?" description="Restoring copies the selected formal revision into current Post state using the current expected version. It does not bypass publishing or field-level authorization." confirmLabel="Restore revision" onCancel={()=>setTarget(undefined)} onConfirm={()=>{if(!target||!expectedVersion)return;void restore.mutateAsync({path:{site_key:site.site_key,post_id:postId,revision_id:target},body:{expected_version:expectedVersion}}).then(()=>postQuery.refetch()).finally(()=>setTarget(undefined))}} /></PageFrame>}

interface SimpleEntityConfig { kind:"category"|"tag"|"author"; listPageId:string; editorPageId:string; listOp:"API15-S-030"|"API15-S-040"|"API15-S-050"; getOp:"API15-S-032"|"API15-S-042"|"API15-S-052"; createOp:"API15-S-031"|"API15-S-041"|"API15-S-051"; updateOp:"API15-S-033"|"API15-S-043"|"API15-S-053"; deleteOp?:"API15-S-034"|"API15-S-044"; retireOp?:"API15-S-054"; idParam:"category_id"|"tag_id"|"author_id"; idKey:"category_id"|"tag_id"|"author_id"; viewPermission:string; createPermission:string; editPermission:string; destructivePermission:string; }
const entityConfigs:Record<string,SimpleEntityConfig>={category:{kind:"category",listPageId:"ADM-S-CAT-01",editorPageId:"ADM-S-CAT-02",listOp:"API15-S-030",getOp:"API15-S-032",createOp:"API15-S-031",updateOp:"API15-S-033",deleteOp:"API15-S-034",idParam:"category_id",idKey:"category_id",viewPermission:"categories.view",createPermission:"categories.create",editPermission:"categories.edit",destructivePermission:"categories.delete"},tag:{kind:"tag",listPageId:"ADM-S-TAG-01",editorPageId:"ADM-S-TAG-02",listOp:"API15-S-040",getOp:"API15-S-042",createOp:"API15-S-041",updateOp:"API15-S-043",deleteOp:"API15-S-044",idParam:"tag_id",idKey:"tag_id",viewPermission:"tags.view",createPermission:"tags.create",editPermission:"tags.edit",destructivePermission:"tags.delete"},author:{kind:"author",listPageId:"ADM-S-AUTHOR-01",editorPageId:"ADM-S-AUTHOR-02",listOp:"API15-S-050",getOp:"API15-S-052",createOp:"API15-S-051",updateOp:"API15-S-053",retireOp:"API15-S-054",idParam:"author_id",idKey:"author_id",viewPermission:"authors.view",createPermission:"authors.create",editPermission:"authors.edit",destructivePermission:"authors.retire"}};
function entityBase(kind:SimpleEntityConfig["kind"]){return kind==="category"?"categories":kind==="tag"?"tags":"authors"}
export function EntityListPage({kind}:{kind:SimpleEntityConfig["kind"]}){const config=entityConfigs[kind]!;const site=useAdminContext().site!;const permissions=useEffectivePermissions();const query=useAdminQuery<UnknownRecord>(config.listOp,{path:{site_key:site.site_key}});const items=listItems(query.data);return <PageFrame pageId={config.listPageId} context={`${site.display_name} · site-owned ${entityBase(kind)}`} actions={permissions.includes(config.createPermission)?<Link className="bp-button bp-button--primary" to={sitePath(site.site_key,`/${entityBase(kind)}/new`)}>Create {kind}</Link>:undefined}><QueryState isLoading={query.isLoading} error={query.error} hasData={Boolean(query.data)} retry={()=>void query.refetch()}><DataTable rows={items} rowKey={r=>stringValue(r,config.idKey)} columns={[{key:"name",header:kind==="author"?"Author":"Name",cell:r=><><Link className="bp-table-primary" to={sitePath(site.site_key,`/${entityBase(kind)}/${stringValue(r,config.idKey)}`)}>{stringValue(r,kind==="author"?"display_name":"name")}</Link><span className="bp-table-secondary">{stringValue(r,"slug")}</span></>},{key:"status",header:"Status",cell:r=><StatusBadge value={stringValue(r,"status","ACTIVE")}/>},{key:"updated",header:"Updated",cell:r=>formatDate(r.updated_at)},{key:"action",header:"Actions",cell:r=><Link className="bp-button bp-button--tertiary" to={sitePath(site.site_key,`/${entityBase(kind)}/${stringValue(r,config.idKey)}`)}>Open</Link>}]} />{kind==="tag"?<TagMergePanel siteKey={site.site_key} tags={items} onComplete={()=>void query.refetch()}/>:null}</QueryState></PageFrame>}

export function EntityEditorPage({kind}:{kind:SimpleEntityConfig["kind"]}){const config=entityConfigs[kind]!;const site=useAdminContext().site!;const permissions=useEffectivePermissions();const params=useParams();const target=params[config.idParam==="category_id"?"categoryId":config.idParam==="tag_id"?"tagId":"authorId"]??"new";const create=target==="new";const allowed=permissions.includes(create?config.createPermission:config.editPermission);const query=useAdminQuery<UnknownRecord>(config.getOp,{path:{site_key:site.site_key,[config.idParam]:target}},!create);const source=asRecord(asRecord(query.data)[kind]);const [name,setName]=useState("");const [slug,setSlug]=useState("");const [description,setDescription]=useState("");const [designation,setDesignation]=useState("");const [expertise,setExpertise]=useState("");const [avatar,setAvatar]=useState("");const [seoTitle,setSeoTitle]=useState("");const [metaDescription,setMetaDescription]=useState("");const [canonical,setCanonical]=useState("");const [indexPolicy,setIndexPolicy]=useState("INHERIT");const dirty=useDirtyState();const navigate=useNavigate();const save=useAdminMutation<UnknownRecord>(create?config.createOp:config.updateOp);const destructive=useAdminMutation(config.deleteOp??config.retireOp!);const [confirm,setConfirm]=useState(false);
useEffect(()=>{if(!create&&query.data){setName(stringValue(source,kind==="author"?"display_name":"name","")==="—"?"":stringValue(source,kind==="author"?"display_name":"name","") );setSlug(stringValue(source,"slug","")==="—"?"":stringValue(source,"slug","") );setDescription(stringValue(source,kind==="author"?"bio":"description","")==="—"?"":stringValue(source,kind==="author"?"bio":"description","") );setDesignation(stringValue(source,"designation","")==="—"?"":stringValue(source,"designation","") );setExpertise(arrayValue(source,"expertise").join(", "));setAvatar(stringValue(source,"avatar_media_id","")==="—"?"":stringValue(source,"avatar_media_id","") );setSeoTitle(stringValue(source,"seo_title","")==="—"?"":stringValue(source,"seo_title","") );setMetaDescription(stringValue(source,"meta_description","")==="—"?"":stringValue(source,"meta_description","") );setCanonical(stringValue(source,"canonical_override","")==="—"?"":stringValue(source,"canonical_override","") );setIndexPolicy(stringValue(source,"index_policy","INHERIT"));dirty.setDirty(false)}},[create,query.data]);function change(fn:(v:string)=>void,v:string){fn(v);dirty.setDirty(true);dirty.setDirtyLabel(`${kind} edits`)}async function submit(e:FormEvent){e.preventDefault();const seoFields=permissions.includes("seo.edit")?{...(seoTitle?{seo_title:seoTitle}:{}),...(metaDescription?{meta_description:metaDescription}:{}),...(canonical?{canonical_override:canonical}:{}),index_policy:indexPolicy}:{};const body:UnknownRecord=kind==="author"?{display_name:name,...(slug?{slug}:{}),...(description?{bio:description}:{}),...(designation?{designation}:{}),expertise:expertise.split(",").map(value=>value.trim()).filter(Boolean),social_profiles:create?[]:arrayValue(source,"social_profiles"),...(avatar?{avatar_media_id:avatar}:{}),...seoFields}:{name,...(slug?{slug}:{}),...(description?{description}:{}),...(kind==="category"?seoFields:{})};const input=create?{path:{site_key:site.site_key},body}:{path:{site_key:site.site_key,[config.idParam]:target},body};const result=await save.mutateAsync(input);dirty.setDirty(false);const entity=asRecord(asRecord(result)[kind]);const id=stringValue(entity,config.idKey,target);if(create&&id!=="—")navigate(sitePath(site.site_key,`/${entityBase(kind)}/${id}`),{replace:true})}
if(!allowed)return <PageFrame pageId={config.editorPageId} required={[config.viewPermission]}><Alert tone="danger">You can view this module but do not have the required {create?"create":"edit"} permission for this mode.</Alert></PageFrame>;
return <PageFrame pageId={config.editorPageId} required={[config.viewPermission]} context={`${create?"Create":"Edit"} ${kind}`} back={<Link to={sitePath(site.site_key,`/${entityBase(kind)}`)}>← Back to list</Link>} actions={!create&&permissions.includes(config.destructivePermission)?<Button variant="destructive" onClick={()=>setConfirm(true)}>{kind==="author"?"Retire":"Delete"}</Button>:undefined}>{!create?<QueryState isLoading={query.isLoading} error={query.error} hasData={Boolean(query.data)} retry={()=>void query.refetch()}><span/></QueryState>:null}<form className="bp-form" onSubmit={submit}><FormSection title={kind==="author"?"Author details":"Category details"}><TextField label="Name" value={name} onChange={e=>change(setName,e.target.value)} required/><TextField label="Slug" value={slug} onChange={e=>change(setSlug,e.target.value)} hint="Leave blank to generate it from the name."/><TextArea label={kind==="author"?"Biography":"Description"} value={description} onChange={e=>change(setDescription,e.target.value)}/>{kind==="author"?<><TextField label="Designation" value={designation} onChange={e=>change(setDesignation,e.target.value)}/><TextField label="Expertise" value={expertise} onChange={e=>change(setExpertise,e.target.value)} hint="Separate areas of expertise with commas."/><MediaPicker siteKey={site.site_key} value={avatar} onSelect={id=>change(setAvatar,id)} label="Choose author photo"/></>:null}</FormSection>{(kind==="category"||kind==="author")&&permissions.includes("seo.view")?<details className="bp-advanced-settings"><summary>Advanced SEO</summary><div className="bp-form-stack"><TextField label="SEO title" value={seoTitle} onChange={e=>change(setSeoTitle,e.target.value)} disabled={!permissions.includes("seo.edit")}/><TextArea label="Meta description" value={metaDescription} onChange={e=>change(setMetaDescription,e.target.value)} disabled={!permissions.includes("seo.edit")}/><TextField label="Canonical URL override" type="url" value={canonical} onChange={e=>change(setCanonical,e.target.value)} disabled={!permissions.includes("seo.edit")}/><SelectField label="Search indexing" value={indexPolicy} onChange={e=>change(setIndexPolicy,e.target.value)} disabled={!permissions.includes("seo.edit")}><option value="INHERIT">Use website default</option><option value="INDEX">Allow indexing</option><option value="NOINDEX">Do not index</option></SelectField></div></details>:null}{save.isError?<Alert tone="danger">{mutationError(save.error)}</Alert>:null}{save.isSuccess?<SuccessState/>:null}<div className="bp-form-actions"><Button variant="primary" type="submit" loading={save.isPending}>{create?"Create":"Save changes"}</Button><Button type="button" onClick={()=>navigate(sitePath(site.site_key,`/${entityBase(kind)}`))}>Cancel</Button></div></form><ConfirmDialog open={confirm} title={`${kind==="author"?"Retire":"Delete"} ${kind}?`} description="This action keeps historical content intact and is checked by the server." confirmLabel={kind==="author"?"Retire":"Delete"} destructive onCancel={()=>setConfirm(false)} onConfirm={()=>{const path={site_key:site.site_key,[config.idParam]:target};void destructive.mutateAsync({path}).then(()=>{dirty.setDirty(false);navigate(sitePath(site.site_key,`/${entityBase(kind)}`))}).finally(()=>setConfirm(false))}}/></PageFrame>}

export function MediaLibraryPage(){const site=useAdminContext().site!;const permissions=useEffectivePermissions();const query=useAdminQuery<UnknownRecord>("API15-S-060",{path:{site_key:site.site_key}});const items=listItems(query.data);const upload=useAdminMutation<UnknownRecord>("API15-S-061",{invalidate:["API15-S-060"]});const [open,setOpen]=useState(false);const [file,setFile]=useState<File>();const [alt,setAlt]=useState("");async function submit(e:FormEvent){e.preventDefault();if(!file)return;await upload.mutateAsync({path:{site_key:site.site_key},body:{file,alt_text:alt||undefined}});setOpen(false);setFile(undefined);setAlt("")}return <PageFrame pageId="ADM-S-MEDIA-01" context={`${site.display_name} · same-site media only`} actions={permissions.includes("media.upload")?<Button variant="primary" onClick={()=>setOpen(true)}>Upload</Button>:undefined}><QueryState isLoading={query.isLoading} error={query.error} hasData={Boolean(query.data)} retry={()=>void query.refetch()}><div className="bp-media-grid">{items.map(m=><Link key={stringValue(m,"media_id")} className="bp-media-tile" to={sitePath(site.site_key,`/media/${stringValue(m,"media_id")}`)}><div className="bp-media-thumb">{typeof m.public_url==="string"?<img src={m.public_url} alt={stringValue(m,"alt_text","")} style={{width:"100%",height:"100%",objectFit:"cover"}}/>:<span>Preview unavailable</span>}</div><div className="bp-media-meta"><strong>{stringValue(m,"title",stringValue(m,"filename"))}</strong><span className="bp-table-secondary">{stringValue(m,"mime_type")} · {stringValue(m,"usage_count","0")} use(s)</span></div></Link>)}</div>{items.length===0?<EmptyState title="No media"/>:null}</QueryState><Modal open={open} title="Upload media" description="The selected file remains site-owned. Private object keys and originals are never exposed by this UI." onClose={()=>setOpen(false)} footer={<><Button onClick={()=>setOpen(false)}>Cancel</Button><Button form="media-upload" type="submit" variant="primary" loading={upload.isPending} disabled={!file}>Upload</Button></>}><form id="media-upload" className="bp-form-stack" onSubmit={submit}>{upload.isError?<Alert tone="danger">{mutationError(upload.error)}</Alert>:null}<TextField label="Choose file" type="file" onChange={e=>setFile(e.target.files?.[0])} required/><TextField label="Alt text" value={alt} onChange={e=>setAlt(e.target.value)}/></form></Modal></PageFrame>}

export function MediaDetailPage(){const site=useAdminContext().site!;const {mediaId=""}=useParams();const permissions=useEffectivePermissions();const query=useAdminQuery<UnknownRecord>("API15-S-062",{path:{site_key:site.site_key,media_id:mediaId}});const usage=useAdminQuery<UnknownRecord>("API15-S-066",{path:{site_key:site.site_key,media_id:mediaId}});const media=asRecord(asRecord(query.data).media);const [alt,setAlt]=useState("");const [caption,setCaption]=useState("");const [credit,setCredit]=useState("");const [title,setTitle]=useState("");const [sourceUrl,setSourceUrl]=useState("");const dirty=useDirtyState();const save=useAdminMutation<UnknownRecord>("API15-S-063",{invalidate:["API15-S-062"]});const del=useAdminMutation("API15-S-065");const navigate=useNavigate();const [confirm,setConfirm]=useState(false);useEffect(()=>{if(query.data){setAlt(stringValue(media,"alt_text","")==="—"?"":stringValue(media,"alt_text",""));setCaption(stringValue(media,"caption","")==="—"?"":stringValue(media,"caption",""));setCredit(stringValue(media,"credit","")==="—"?"":stringValue(media,"credit",""));setTitle(stringValue(media,"title","")==="—"?"":stringValue(media,"title",""));setSourceUrl(stringValue(media,"source_url","")==="—"?"":stringValue(media,"source_url",""));dirty.setDirty(false)}},[query.data]);function set(fn:(v:string)=>void,v:string){fn(v);dirty.setDirty(true);dirty.setDirtyLabel("media metadata edits")};async function submit(e:FormEvent){e.preventDefault();await save.mutateAsync({path:{site_key:site.site_key,media_id:mediaId},body:{alt_text:alt,caption,credit,title,source_url:sourceUrl||undefined}});dirty.setDirty(false)}return <PageFrame pageId="ADM-S-MEDIA-02" context={stringValue(media,"filename","Media asset")} back={<Link to={sitePath(site.site_key,"/media")}>← Back to Media</Link>} actions={<><MediaReplacePanel siteKey={site.site_key} mediaId={mediaId} onComplete={()=>void query.refetch()}/>{permissions.includes("media.delete")?<Button variant="destructive" onClick={()=>setConfirm(true)}>Delete</Button>:null}</>}><QueryState isLoading={query.isLoading} error={query.error} hasData={Boolean(query.data)} retry={()=>void query.refetch()}><div className="bp-grid bp-grid--2"><section className="bp-card"><div className="bp-media-thumb" style={{aspectRatio:"16/10"}}>{typeof media.public_url==="string"?<img src={media.public_url} alt={alt} style={{width:"100%",height:"100%",objectFit:"contain"}}/>:<span>Verified derivative unavailable</span>}</div><JsonSummary value={{mime_type:media.mime_type,size_bytes:media.size_bytes,width:media.width,height:media.height,status:media.status,usage_count:media.usage_count,variants:Array.isArray(media.variants)?media.variants:[]}}/></section><form className="bp-form" onSubmit={submit}><FormSection title="Editorial metadata"><TextField label="Title" value={title} onChange={e=>set(setTitle,e.target.value)} disabled={!permissions.includes("media.edit")}/><TextField label="Alt text" value={alt} onChange={e=>set(setAlt,e.target.value)} disabled={!permissions.includes("media.edit")}/><TextArea label="Caption" value={caption} onChange={e=>set(setCaption,e.target.value)} disabled={!permissions.includes("media.edit")}/><TextField label="Credit" value={credit} onChange={e=>set(setCredit,e.target.value)} disabled={!permissions.includes("media.edit")}/><TextField label="Source URL" type="url" value={sourceUrl} onChange={e=>set(setSourceUrl,e.target.value)} disabled={!permissions.includes("media.edit")}/>{save.isError?<Alert tone="danger">{mutationError(save.error)}</Alert>:null}{save.isSuccess?<SuccessState/>:null}{permissions.includes("media.edit")?<Button type="submit" variant="primary" loading={save.isPending}>Save metadata</Button>:null}</FormSection></form></div><section className="bp-card"><div className="bp-card-header"><div><h2>Usage</h2><p>Deletion remains subject to authoritative same-site usage safety.</p></div></div>{usage.isLoading?<p>Loading usage…</p>:<JsonSummary value={usage.data}/>}</section></QueryState><ConfirmDialog open={confirm} title="Delete media?" description="Deletion may be blocked when authoritative usage still exists. The UI will not promise deletion before server acceptance." confirmLabel="Delete media" destructive onCancel={()=>setConfirm(false)} onConfirm={()=>{void del.mutateAsync({path:{site_key:site.site_key,media_id:mediaId}}).then(()=>navigate(sitePath(site.site_key,"/media"))).finally(()=>setConfirm(false))}}/></PageFrame>}

function NavigationMenuEditor({title,items,onChange,disabled,onSave,saving}:{title:string;items:UnknownRecord[];onChange(items:UnknownRecord[]):void;disabled:boolean;onSave():void;saving:boolean}){function patchItem(index:number,patch:UnknownRecord){onChange(items.map((item,current)=>current===index?{...item,...patch}:item))}function move(index:number,delta:number){const target=index+delta;if(target<0||target>=items.length)return;const next=[...items];[next[index],next[target]]=[next[target]!,next[index]!];onChange(next)}return <FormSection title={title} description="Build links in the order visitors should see them.">{items.length===0?<EmptyState title={`No ${title.toLowerCase()} links`}/>:items.map((item,index)=>{const destination=asRecord(item.destination);const kind=stringValue(destination,"kind","HOME");return <div className="bp-card" key={index}><TextField label="Label" value={stringValue(item,"label","")==="—"?"":stringValue(item,"label","")} onChange={e=>patchItem(index,{label:e.target.value})} disabled={disabled}/><SelectField label="Link type" value={kind} onChange={e=>patchItem(index,{destination:e.target.value==="EXTERNAL"?{kind:"EXTERNAL",url:"https://"}:e.target.value==="STATIC"?{kind:"STATIC",static_page_key:"ABOUT"}:{kind:e.target.value}})} disabled={disabled}><option value="HOME">Homepage</option><option value="SEARCH">Search</option><option value="STATIC">Information page</option><option value="EXTERNAL">External URL</option></SelectField>{kind==="EXTERNAL"?<TextField label="URL" type="url" value={stringValue(destination,"url","")==="—"?"":stringValue(destination,"url","")} onChange={e=>patchItem(index,{destination:{kind:"EXTERNAL",url:e.target.value}})} disabled={disabled}/>:null}{kind==="STATIC"?<SelectField label="Page" value={stringValue(destination,"static_page_key","ABOUT")} onChange={e=>patchItem(index,{destination:{kind:"STATIC",static_page_key:e.target.value}})} disabled={disabled}>{["ABOUT","CONTACT","PRIVACY","TERMS","DISCLAIMER"].map(key=><option key={key}>{key}</option>)}</SelectField>:null}<div className="bp-inline-actions"><Button type="button" variant="tertiary" onClick={()=>move(index,-1)} disabled={disabled||index===0}>Move up</Button><Button type="button" variant="tertiary" onClick={()=>move(index,1)} disabled={disabled||index===items.length-1}>Move down</Button><Button type="button" variant="destructive" onClick={()=>onChange(items.filter((_,current)=>current!==index))} disabled={disabled}>Remove</Button></div></div>})}<div className="bp-form-actions"><Button type="button" onClick={()=>onChange([...items,{label:"New link",destination:{kind:"HOME"},children:[]}])} disabled={disabled}>Add link</Button><Button type="button" variant="primary" onClick={onSave} loading={saving} disabled={disabled}>Save {title}</Button></div></FormSection>}

export function NavigationPage(){
  const site=useAdminContext().site!;
  const permissions=useEffectivePermissions();
  const canManage=permissions.includes("navigation.manage");
  const navQuery=useAdminQuery<UnknownRecord>("API15-S-070",{path:{site_key:site.site_key}});
  const homepageQuery=useAdminQuery<UnknownRecord>("API15-S-072",{path:{site_key:site.site_key}});
  const postsQuery=useAdminQuery<UnknownRecord>("API15-S-010",{path:{site_key:site.site_key},query:{status:"PUBLISHED",page:1,page_size:100,sort:"UPDATED_DESC"}},permissions.includes("posts.view"));
  const categoriesQuery=useAdminQuery<UnknownRecord>("API15-S-030",{path:{site_key:site.site_key},query:{page:1,page_size:100}},permissions.includes("categories.view"));
  const [header,setHeader]=useState<UnknownRecord[]>([]);
  const [footer,setFooter]=useState<UnknownRecord[]>([]);
  const [leadPostId,setLeadPostId]=useState("");
  const [sections,setSections]=useState<UnknownRecord[]>([]);
  const dirty=useDirtyState();
  const saveMenu=useAdminMutation<UnknownRecord>("API15-S-071");
  const saveHomepage=useAdminMutation<UnknownRecord>("API15-S-073");
  const publishedPosts=listItems(postsQuery.data);
  const categories=listItems(categoriesQuery.data);

  useEffect(()=>{if(navQuery.data){const n=asRecord(navQuery.data);setHeader(asRecords(asRecord(n.header).items));setFooter(asRecords(asRecord(n.footer).items));dirty.setDirty(false)}},[navQuery.data]);
  useEffect(()=>{if(homepageQuery.data){const homepage=asRecord(asRecord(homepageQuery.data).homepage);const lead=stringValue(homepage,"lead_post_id","");setLeadPostId(lead==="—"?"":lead);setSections(asRecords(homepage.sections));dirty.setDirty(false)}},[homepageQuery.data]);

  function markDirty(label:string){dirty.setDirty(true);dirty.setDirtyLabel(label)}
  function changeMenu(menu:"HEADER"|"FOOTER",items:UnknownRecord[]){menu==="HEADER"?setHeader(items):setFooter(items);markDirty("navigation changes")}
  function patchSection(index:number,patch:UnknownRecord){setSections(current=>current.map((section,currentIndex)=>currentIndex===index?{...section,...patch}:section));markDirty("homepage changes")}
  function toggleSectionValue(index:number,key:"post_ids"|"category_ids",id:string,checked:boolean){const current=arrayValue(sections[index]??{},key).map(String);patchSection(index,{[key]:checked?[...current.filter(value=>value!==id),id]:current.filter(value=>value!==id)})}
  async function saveMenuItems(menu:"HEADER"|"FOOTER"){await saveMenu.mutateAsync({path:{site_key:site.site_key,menu_key:menu},body:{items:menu==="HEADER"?header:footer}});dirty.setDirty(false);void navQuery.refetch()}
  async function saveHomepageSettings(){await saveHomepage.mutateAsync({path:{site_key:site.site_key},body:{...(leadPostId?{lead_post_id:leadPostId}:{}),sections:sections.map(section=>({section_key:stringValue(section,"section_key"),section_kind:stringValue(section,"section_kind"),enabled:booleanValue(section,"enabled"),...(stringValue(section,"display_label","")&&stringValue(section,"display_label","")!=="—"?{display_label:stringValue(section,"display_label")}:{}),...(arrayValue(section,"post_ids").length?{post_ids:arrayValue(section,"post_ids")}:{}),...(arrayValue(section,"category_ids").length?{category_ids:arrayValue(section,"category_ids")}:{} )}))}});dirty.setDirty(false);void homepageQuery.refetch()}

  return <PageFrame pageId="ADM-S-NAV-01">
    <QueryState isLoading={navQuery.isLoading} error={navQuery.error} hasData={Boolean(navQuery.data)} retry={()=>void navQuery.refetch()}>
      <div className="bp-grid bp-grid--2"><NavigationMenuEditor title="Header menu" items={header} onChange={items=>changeMenu("HEADER",items)} disabled={!canManage} onSave={()=>void saveMenuItems("HEADER")} saving={saveMenu.isPending}/><NavigationMenuEditor title="Footer menu" items={footer} onChange={items=>changeMenu("FOOTER",items)} disabled={!canManage} onSave={()=>void saveMenuItems("FOOTER")} saving={saveMenu.isPending}/></div>
      {saveMenu.isError?<Alert tone="danger">{mutationError(saveMenu.error)}</Alert>:null}{saveMenu.isSuccess?<SuccessState>Navigation saved.</SuccessState>:null}
    </QueryState>
    <QueryState isLoading={homepageQuery.isLoading} error={homepageQuery.error} hasData={Boolean(homepageQuery.data)} retry={()=>void homepageQuery.refetch()}>
      <FormSection title="Homepage controls" description="Choose the lead blog and control the sections displayed on this website's homepage.">
        <SelectField label="Lead blog" value={leadPostId} onChange={event=>{setLeadPostId(event.target.value);markDirty("homepage changes")}} disabled={!canManage||postsQuery.isLoading}>
          <option value="">No lead blog</option>{publishedPosts.map(post=><option key={stringValue(post,"post_id")} value={stringValue(post,"post_id")}>{stringValue(post,"title","Untitled blog")}</option>)}
        </SelectField>
        {sections.length===0?<EmptyState title="No homepage sections configured" description="This website has no editable homepage sections."/>:sections.map((section,index)=>{const kind=stringValue(section,"section_kind");const selectedPosts=arrayValue(section,"post_ids").map(String);const selectedCategories=arrayValue(section,"category_ids").map(String);return <div className="bp-card" key={stringValue(section,"section_key",String(index))}>
          <Checkbox label={stringValue(section,"display_label",stringValue(section,"section_key"))} checked={booleanValue(section,"enabled")} onChange={event=>patchSection(index,{enabled:event.target.checked})} disabled={!canManage}/>
          <TextField label="Section label" value={stringValue(section,"display_label","")==="—"?"":stringValue(section,"display_label","")} onChange={event=>patchSection(index,{display_label:event.target.value})} disabled={!canManage}/>
          {kind==="POST_SELECTION"?<div className="bp-field"><span className="bp-field-label">Blogs in this section</span>{publishedPosts.length?publishedPosts.map(post=>{const id=stringValue(post,"post_id");return <Checkbox key={id} label={stringValue(post,"title","Untitled blog")} checked={selectedPosts.includes(id)} onChange={event=>toggleSectionValue(index,"post_ids",id,event.target.checked)} disabled={!canManage}/> }):<p className="bp-field-hint">Publish a blog before adding it to this section.</p>}</div>:null}
          {kind==="CATEGORY_SELECTION"?<div className="bp-field"><span className="bp-field-label">Categories in this section</span>{categories.length?categories.map(category=>{const id=stringValue(category,"category_id");return <Checkbox key={id} label={stringValue(category,"name","Unnamed category")} checked={selectedCategories.includes(id)} onChange={event=>toggleSectionValue(index,"category_ids",id,event.target.checked)} disabled={!canManage}/> }):<p className="bp-field-hint">Create a category before adding it to this section.</p>}</div>:null}
        </div>})}
        {saveHomepage.isError?<Alert tone="danger">{mutationError(saveHomepage.error)}</Alert>:null}{saveHomepage.isSuccess?<SuccessState>Homepage controls saved.</SuccessState>:null}
        {canManage?<Button type="button" variant="primary" onClick={()=>void saveHomepageSettings()} loading={saveHomepage.isPending}>Save homepage</Button>:null}
      </FormSection>
    </QueryState>
  </PageFrame>
}

export function SeoPage(){const site=useAdminContext().site!;const permissions=useEffectivePermissions();const query=useAdminQuery<UnknownRecord>("API15-S-080",{path:{site_key:site.site_key}});const seo=asRecord(asRecord(query.data).seo);const [title,setTitle]=useState("");const [description,setDescription]=useState("");const [indexPolicy,setIndexPolicy]=useState("INHERIT");const [robots,setRobots]=useState("INHERIT");const [image,setImage]=useState("");const dirty=useDirtyState();const save=useAdminMutation<UnknownRecord>("API15-S-081");useEffect(()=>{if(query.data){setTitle(stringValue(seo,"seo_title","")==="—"?"":stringValue(seo,"seo_title",""));setDescription(stringValue(seo,"meta_description","")==="—"?"":stringValue(seo,"meta_description",""));setIndexPolicy(stringValue(seo,"index_policy","INHERIT"));setRobots(stringValue(seo,"link_robots_policy","INHERIT"));setImage(stringValue(seo,"default_social_image_media_id","")==="—"?"":stringValue(seo,"default_social_image_media_id",""));dirty.setDirty(false)}},[query.data]);function change(fn:(v:string)=>void,v:string){fn(v);dirty.setDirty(true);dirty.setDirtyLabel("SEO setting changes")}async function submit(e:FormEvent){e.preventDefault();await save.mutateAsync({path:{site_key:site.site_key},body:{seo_title:title||undefined,meta_description:description||undefined,index_policy:indexPolicy,link_robots_policy:robots,default_social_image_media_id:image||undefined}});dirty.setDirty(false)}const disabled=!permissions.includes("seo.edit");return <PageFrame pageId="ADM-S-SEO-01" context={`${site.display_name} search and sharing defaults`}><QueryState isLoading={query.isLoading} error={query.error} hasData={Boolean(query.data)} retry={()=>void query.refetch()}><form className="bp-form" onSubmit={submit}><FormSection title="SEO defaults"><TextField label="Default SEO title" value={title} onChange={e=>change(setTitle,e.target.value)} disabled={disabled}/><TextArea label="Default meta description" value={description} onChange={e=>change(setDescription,e.target.value)} disabled={disabled}/><MediaPicker siteKey={site.site_key} value={image} onSelect={id=>change(setImage,id)} label="Choose default social image" disabled={disabled}/><details className="bp-advanced-settings"><summary>Advanced SEO</summary><div className="bp-form-stack"><SelectField label="Search indexing" value={indexPolicy} onChange={e=>change(setIndexPolicy,e.target.value)} disabled={disabled}><option value="INHERIT">Use platform default</option><option value="INDEX">Allow indexing</option><option value="NOINDEX">Do not index</option></SelectField><SelectField label="Link following" value={robots} onChange={e=>change(setRobots,e.target.value)} disabled={disabled}><option value="INHERIT">Use platform default</option><option value="FOLLOW">Allow following</option><option value="NOFOLLOW">Do not follow</option></SelectField></div></details>{save.isError?<Alert tone="danger">{mutationError(save.error)}</Alert>:null}{save.isSuccess?<SuccessState>SEO defaults saved.</SuccessState>:null}{!disabled?<Button variant="primary" type="submit" loading={save.isPending}>Save SEO defaults</Button>:null}</FormSection></form></QueryState></PageFrame>}

export function RedirectsListPage(){const site=useAdminContext().site!;const permissions=useEffectivePermissions();const query=useAdminQuery<UnknownRecord>("API15-S-082",{path:{site_key:site.site_key}});const items=listItems(query.data);return <PageFrame pageId="ADM-S-REDIR-01" context={`${site.display_name} · site-owned redirects`} actions={permissions.includes("redirects.create")?<Link className="bp-button bp-button--primary" to={sitePath(site.site_key,"/redirects/new")}>Create redirect</Link>:undefined}><QueryState isLoading={query.isLoading} error={query.error} hasData={Boolean(query.data)} retry={()=>void query.refetch()}><DataTable rows={items} rowKey={r=>stringValue(r,"redirect_id")} columns={[{key:"source",header:"Source",cell:r=><Link className="bp-table-primary" to={sitePath(site.site_key,`/redirects/${stringValue(r,"redirect_id")}`)}>{stringValue(r,"source_path")}</Link>},{key:"dest",header:"Destination",cell:r=>stringValue(r,"destination_url")},{key:"status",header:"HTTP",cell:r=>stringValue(r,"status_code")},{key:"active",header:"State",cell:r=><StatusBadge value={booleanValue(r,"is_active")?"ACTIVE":"DISABLED"}/>},{key:"updated",header:"Updated",cell:r=>formatDate(r.updated_at)}]}/></QueryState></PageFrame>}

export function RedirectEditorPage(){const site=useAdminContext().site!;const permissions=useEffectivePermissions();const {redirectId="new"}=useParams();const create=redirectId==="new";const query=useAdminQuery<UnknownRecord>("API15-S-084",{path:{site_key:site.site_key,redirect_id:redirectId}},!create);const resource=asRecord(asRecord(query.data).redirect);const [source,setSource]=useState("");const [dest,setDest]=useState("");const [status,setStatus]=useState("301");const [active,setActive]=useState(true);const dirty=useDirtyState();const save=useAdminMutation<UnknownRecord>(create?"API15-S-083":"API15-S-085");const del=useAdminMutation("API15-S-086");const navigate=useNavigate();const [confirm,setConfirm]=useState(false);useEffect(()=>{if(query.data){setSource(stringValue(resource,"source_path",""));setDest(stringValue(resource,"destination_url",""));setStatus(stringValue(resource,"status_code","301"));setActive(booleanValue(resource,"is_active"));dirty.setDirty(false)}},[query.data]);const need=create?"redirects.create":"redirects.edit";if(!permissions.includes(need))return <PageFrame pageId="ADM-S-REDIR-02" required={["redirects.view"]}><Alert tone="danger">You do not have {need}.</Alert></PageFrame>;function mark(){dirty.setDirty(true);dirty.setDirtyLabel("redirect changes")}async function submit(e:FormEvent){e.preventDefault();const body={source_path:source,destination_url:dest,status_code:Number(status),is_active:active};const result=await save.mutateAsync(create?{path:{site_key:site.site_key},body}:{path:{site_key:site.site_key,redirect_id:redirectId},body});dirty.setDirty(false);const id=stringValue(asRecord(asRecord(result).redirect),"redirect_id",redirectId);if(create)navigate(sitePath(site.site_key,`/redirects/${id}`),{replace:true})}return <PageFrame pageId="ADM-S-REDIR-02" required={["redirects.view"]} context={create?"Create redirect":"Edit redirect"} back={<Link to={sitePath(site.site_key,"/redirects")}>← Back to Redirects</Link>} actions={!create&&permissions.includes("redirects.delete")?<Button variant="destructive" onClick={()=>setConfirm(true)}>Delete</Button>:undefined}><form className="bp-form" onSubmit={submit}><FormSection title="Redirect"><TextField label="Source path" value={source} onChange={e=>{setSource(e.target.value);mark()}} placeholder="/old-path" required/><TextField label="Destination URL" type="url" value={dest} onChange={e=>{setDest(e.target.value);mark()}} required/><SelectField label="Status code" value={status} onChange={e=>{setStatus(e.target.value);mark()}}><option value="301">301 Permanent</option><option value="302">302 Temporary</option></SelectField><Checkbox label="Active" checked={active} onChange={e=>{setActive(e.target.checked);mark()}}/>{save.isError?<Alert tone="danger">{mutationError(save.error)}</Alert>:null}{save.isSuccess?<SuccessState/>:null}<Button variant="primary" type="submit" loading={save.isPending}>{create?"Create redirect":"Save redirect"}</Button></FormSection></form><ConfirmDialog open={confirm} title="Delete redirect?" description="The server applies routing conflict and integrity rules before deletion." confirmLabel="Delete redirect" destructive onCancel={()=>setConfirm(false)} onConfirm={()=>void del.mutateAsync({path:{site_key:site.site_key,redirect_id:redirectId}}).then(()=>navigate(sitePath(site.site_key,"/redirects"))).finally(()=>setConfirm(false))}/></PageFrame>}

export function SearchIndexingPage(){const site=useAdminContext().site!;const permissions=useEffectivePermissions();const statusQuery=useAdminQuery<UnknownRecord>("API15-S-093",{path:{site_key:site.site_key}});const [q,setQ]=useState("");const [submitted,setSubmitted]=useState("");const searchQuery=useAdminQuery<UnknownRecord>("API15-S-090",{path:{site_key:site.site_key},query:{q:submitted||undefined,page:1,page_size:20}},Boolean(submitted));const reindex=useAdminMutation<UnknownRecord>("API15-S-094");const status=asRecord(statusQuery.data);const results=listItems(searchQuery.data);return <PageFrame pageId="ADM-S-SEARCH-01" context={`${site.display_name} · search diagnostics remain site-scoped`} actions={permissions.includes("search.reindex")?<Button variant="secondary" onClick={()=>void reindex.mutateAsync({path:{site_key:site.site_key},body:{reason:"Admin requested reindex"}})}>Request reindex</Button>:undefined}><div className="bp-grid bp-grid--stats"><StatCard label="Index state" value={<StatusBadge value={stringValue(status,"state","READY")}/>} note={formatDate(status.last_indexed_at)}/></div>{reindex.isSuccess?<Alert tone="success">Reindex command accepted. Search remains derived state; this acknowledgement is not completion.</Alert>:null}<section className="bp-card"><div className="bp-card-header"><div><h2>Editorial post search</h2><p>Queries API15-S-090 inside the current site.</p></div></div><FilterBar><TextField label="Query" value={q} onChange={e=>setQ(e.target.value)}/><Button variant="primary" onClick={()=>setSubmitted(q.trim())}>Search</Button></FilterBar>{submitted?<QueryState isLoading={searchQuery.isLoading} error={searchQuery.error} hasData={Boolean(searchQuery.data)} retry={()=>void searchQuery.refetch()}><DataTable rows={results} rowKey={r=>stringValue(r,"post_id",stringValue(r,"id"))} columns={[{key:"title",header:"Result",cell:r=><span className="bp-table-primary">{stringValue(r,"title")}</span>},{key:"status",header:"Status",cell:r=><StatusBadge value={stringValue(r,"status","DRAFT")}/>},{key:"updated",header:"Updated",cell:r=>formatDate(r.updated_at)}]}/></QueryState>:<EmptyState title="Enter a query" description="No cross-site search fallback is performed."/>}</section></PageFrame>}

export function EditorialCalendarPage(){const site=useAdminContext().site!;const timezone=site.timezone_id??"Asia/Kolkata";const today=new Date();const monthAgo=new Date(today);monthAgo.setDate(today.getDate()-30);const monthAhead=new Date(today);monthAhead.setDate(today.getDate()+60);const [from,setFrom]=useState(monthAgo.toISOString().slice(0,10));const [to,setTo]=useState(monthAhead.toISOString().slice(0,10));const fromInstant=new Date(`${from}T00:00:00`).toISOString();const toInstant=new Date(`${to}T23:59:59.999`).toISOString();const query=useAdminQuery<UnknownRecord>("API15-S-095",{path:{site_key:site.site_key},query:{from:fromInstant,to:toInstant}});const items=asRecords(asRecord(query.data).items);const localTime=(value:unknown)=>{if(!value)return "—";const date=new Date(String(value));return Number.isNaN(date.getTime())?"—":new Intl.DateTimeFormat(undefined,{dateStyle:"medium",timeStyle:"short",timeZone:timezone}).format(date)};return <PageFrame pageId="ADM-S-CAL-01" context={`${site.display_name} · ${timezone}`}><Alert tone="info">Scheduled and published blogs appear here in the website timezone. Select a title to open it.</Alert><FilterBar><TextField label="From" type="date" value={from} onChange={e=>setFrom(e.target.value)}/><TextField label="To" type="date" value={to} onChange={e=>setTo(e.target.value)}/></FilterBar><QueryState isLoading={query.isLoading} error={query.error} hasData={Boolean(query.data)} retry={()=>void query.refetch()}><DataTable rows={items} rowKey={r=>stringValue(r,"post_id")} empty={<EmptyState title="No scheduled or published blogs" description="Nothing falls within the selected dates."/>} columns={[{key:"post",header:"Blog",cell:r=><Link className="bp-table-primary" to={sitePath(site.site_key,`/posts/${stringValue(r,"post_id")}`)}>{stringValue(r,"title","Untitled")}</Link>},{key:"status",header:"Status",cell:r=><StatusBadge value={stringValue(r,"status","DRAFT")}/>},{key:"scheduled",header:`Scheduled (${timezone})`,cell:r=>localTime(r.scheduled_for)},{key:"published",header:`Published (${timezone})`,cell:r=>localTime(r.published_at)}]}/></QueryState></PageFrame>}

export function SiteSettingsPage(){
  const site=useAdminContext().site!;const permissions=useEffectivePermissions();const query=useAdminQuery<UnknownRecord>("API15-S-096",{path:{site_key:site.site_key}});const [values,setValues]=useState<Record<string,unknown>>({});const dirty=useDirtyState();const save=useAdminMutation<UnknownRecord>("API15-S-097");
  useEffect(()=>{if(query.data){const next:Record<string,unknown>={};for(const entry of asRecords(asRecord(query.data).settings))next[stringValue(entry,"key")]=entry.value;setValues(next);dirty.setDirty(false)}},[query.data]);
  function set(key:string,value:unknown){setValues(current=>({...current,[key]:value}));dirty.setDirty(true);dirty.setDirtyLabel("site setting changes")}
  function objectValue(group:string,key:string){return String(asRecord(values[group])[key]??"")}
  function setObject(group:string,key:string,value:string){set(group,{...asRecord(values[group]),[key]:value})}
  async function submit(e:FormEvent){e.preventDefault();const settings=Object.entries(values).map(([key,value])=>({key,value}));await save.mutateAsync({path:{site_key:site.site_key},body:{settings}});dirty.setDirty(false);void query.refetch()}
  const disabled=!permissions.includes("site_settings.edit");
  return <PageFrame pageId="ADM-S-SET-01" context={`${site.display_name} settings`}><QueryState isLoading={query.isLoading} error={query.error} hasData={Boolean(query.data)} retry={()=>void query.refetch()}><form className="bp-form" onSubmit={submit}>
    <FormSection title="Website identity"><TextField label="Website name" value={String(values.display_name??"")} onChange={e=>set("display_name",e.target.value)} disabled={disabled}/><TextField label="Language" value={String(values.default_language_code??"")} onChange={e=>set("default_language_code",e.target.value)} disabled={disabled}/><TextField label="Locale" value={String(values.locale_code??"")} onChange={e=>set("locale_code",e.target.value)} disabled={disabled}/><TextField label="Timezone" value={String(values.timezone_id??"")} onChange={e=>set("timezone_id",e.target.value)} disabled={disabled}/></FormSection>
    <FormSection title="Brand and footer"><MediaPicker siteKey={site.site_key} value={String(values.logo_media_id??"")} onSelect={id=>set("logo_media_id",id)} label="Choose logo" disabled={disabled}/><MediaPicker siteKey={site.site_key} value={String(values.favicon_media_id??"")} onSelect={id=>set("favicon_media_id",id)} label="Choose favicon" disabled={disabled}/><MediaPicker siteKey={site.site_key} value={String(values.default_social_image_media_id??"")} onSelect={id=>set("default_social_image_media_id",id)} label="Choose default social image" disabled={disabled}/><TextField label="Copyright text" value={String(values.copyright_text??"")} onChange={e=>set("copyright_text",e.target.value)} disabled={disabled}/></FormSection>
    <FormSection title="Contact information"><TextField label="Email" type="email" value={objectValue("contact_info","email")} onChange={e=>setObject("contact_info","email",e.target.value)} disabled={disabled}/><TextField label="Phone" value={objectValue("contact_info","phone")} onChange={e=>setObject("contact_info","phone",e.target.value)} disabled={disabled}/><TextArea label="Address" value={objectValue("contact_info","address")} onChange={e=>setObject("contact_info","address",e.target.value)} disabled={disabled}/><TextField label="Opening hours" value={objectValue("contact_info","hours")} onChange={e=>setObject("contact_info","hours",e.target.value)} disabled={disabled}/></FormSection>
    <FormSection title="Social profiles"><TextField label="Facebook URL" type="url" value={objectValue("social_profiles","facebook")} onChange={e=>setObject("social_profiles","facebook",e.target.value)} disabled={disabled}/><TextField label="Instagram URL" type="url" value={objectValue("social_profiles","instagram")} onChange={e=>setObject("social_profiles","instagram",e.target.value)} disabled={disabled}/><TextField label="YouTube URL" type="url" value={objectValue("social_profiles","youtube")} onChange={e=>setObject("social_profiles","youtube",e.target.value)} disabled={disabled}/><TextField label="X URL" type="url" value={objectValue("social_profiles","x")} onChange={e=>setObject("social_profiles","x",e.target.value)} disabled={disabled}/></FormSection>
    <details className="bp-advanced-settings"><summary>Analytics and site verification</summary><div className="bp-form-stack"><TextField label="Google Analytics ID" value={objectValue("analytics_verification","google_analytics_id")} onChange={e=>setObject("analytics_verification","google_analytics_id",e.target.value)} disabled={disabled}/><TextField label="Google Search Console verification" value={objectValue("analytics_verification","google_search_console")} onChange={e=>setObject("analytics_verification","google_search_console",e.target.value)} disabled={disabled}/><TextField label="Bing site verification" value={objectValue("analytics_verification","bing_site_verification")} onChange={e=>setObject("analytics_verification","bing_site_verification",e.target.value)} disabled={disabled}/></div></details>
    {save.isError?<Alert tone="danger">{mutationError(save.error)}</Alert>:null}{save.isSuccess?<SuccessState>Website settings saved.</SuccessState>:null}{!disabled?<Button variant="primary" type="submit" loading={save.isPending}>Save settings</Button>:null}
  </form></QueryState></PageFrame>
}
